      }
      const sourceBytes = Buffer.from(input.sourceBase64, 'base64');
      if (sourceBytes.toString('base64') !== input.sourceBase64) fail('SOURCE_BASE64_NOT_CANONICAL');
      return admitPinnedSeller({ journal: catalog, sourceBytes,
        sellerId: input.sellerId, sequence: input.sequence,
        sourceURL: input.sourceURL, observedAt: input.observedAt, proofs: input.proofs,
        authority: selected.authority, pinnedPublicKey: selected.pinnedPublicKey });
    }
    if (command.operation === 'preview-batch' || command.operation === 'apply-batch') {
      const apply = command.operation === 'apply-batch';
      fields(input, apply ? ['batch','expectedHead','expectedPlan','expectedBatch','expectedPolicy'] : ['batch']);
      fields(input.batch, ['schema','admissions']);
      if (input.batch.schema !== SIGNED_BATCH_SCHEMA || !Array.isArray(input.batch.admissions) ||
          !input.batch.admissions.length || input.batch.admissions.length > MAX_BATCH_OPERATIONS)
        fail('SIGNED_BATCH_SCHEMA_INVALID');
      const batchSha256 = sha(JSON.stringify(input.batch));
      if (apply && (input.expectedBatch !== batchSha256 || input.expectedPolicy !== policy.sourceSha256))
        fail('SIGNED_BATCH_SOURCE_OR_POLICY_CHANGED');
      if (apply && (typeof input.expectedHead !== 'string' || !/^[a-f0-9]{64}$/.test(input.expectedHead) ||
          typeof input.expectedPlan !== 'string' || !/^[a-f0-9]{64}$/.test(input.expectedPlan)))
        fail('SIGNED_BATCH_REVIEW_REQUIRED');
      const now = Date.now();
      let expiresAt = Infinity, verifiedPaymentOptions = 0;
      const operations = input.batch.admissions.map((row,index)=>{
        try {
          fields(row, ['sellerId','sequence','sourceURL','observedAt','sourceBase64','proofs']);
          const selected = sellerPolicy(row.sellerId);
          if (typeof row.sourceBase64 !== 'string' || row.sourceBase64.length > 87384)
            fail('ORIGINAL_SOURCE_BYTES_REQUIRED');
          const sourceBytes = Buffer.from(row.sourceBase64,'base64');
          if (sourceBytes.toString('base64') !== row.sourceBase64) fail('SOURCE_BASE64_NOT_CANONICAL');
          const prepared = verifyPinnedSellerAdmission({...row, sourceBytes,
            authority:selected.authority,pinnedPublicKey:selected.pinnedPublicKey,now});
          expiresAt = Math.min(expiresAt,prepared.verification.expiresAt);
          verifiedPaymentOptions += prepared.verification.verifiedPaymentOptions;
          return prepared.operation;
        } catch(error) {
          const code = /^[A-Z0-9_]{1,70}$/.test(error?.message ?? '') ? error.message : 'SELLER_PROOF_REJECTED';
          fail(`SIGNED_BATCH_ITEM_${index}_${code}`);
        }
      });
      if (!apply) return {schema:SIGNED_BATCH_PLAN_SCHEMA,batchSha256,
        policySha256:policy.sourceSha256,expiresAt:new Date(expiresAt).toISOString(),
        verifiedPaymentOptions,review:await catalog.previewBatch(operations)};
      // Proofs are freshly checked above on EVERY apply, not trusted from a saved review.
      const result = await catalog.commitBatch(operations,{expectedHead:input.expectedHead,expectedPlan:input.expectedPlan});
      return {schema:'stellar-forge.catalog-signed-batch-receipt/v1',decision:result.decision,
        head:result.head,operations:result.operationsAfter,changes:result.applied,replays:result.replayed,
        batchSha256,policySha256:policy.sourceSha256,verifiedPaymentOptions,paymentCalls:0,signaturesIssued:0};
    }
    if (command.operation === 'prepare-withdrawal') {
      fields(input, ['sellerId', 'catalogKey', 'sourceURL', 'reason']);
      const selected = sellerPolicy(input.sellerId);
      const current = catalog.lookupCatalogKey(input.catalogKey);
      if (!current || current.signer !== selected.authority.signer) fail('CURRENT_SELLER_PIN_MISMATCH');
      return prepareWithdrawal({ journal: catalog, ...input });
    }
    if (command.operation === 'apply-withdrawal') {
      fields(input, ['envelope']);
      const selected = sellerPolicy(input.envelope?.request?.sellerId);
      return applyWithdrawal({ journal: catalog, envelope: input.envelope,
        pinnedPublicKey: selected.pinnedPublicKey });
    }
    fail('UNKNOWN_OPERATOR_COMMAND');
  };
  const serialize = command => {
    const task = queue.then(() => execute(command));
    queue = task.catch(() => {});
    pending.add(task);
    void task.finally(() => pending.delete(task)).catch(() => {});
    return task;
  };
  const send = (res, status, payload) => {
    if (res.destroyed || res.writableEnded) return;
    let body = JSON.stringify(payload);
    if (Buffer.byteLength(body) > MAX_RESPONSE) {
      status = 413; body = JSON.stringify({ ok: false, error: 'RESPONSE_TOO_LARGE_USE_PAGINATION' });
    }
    res.writeHead(status, { 'content-type': 'application/json; charset=utf-8',
      'content-length': Buffer.byteLength(body), 'cache-control': 'no-store',
      'connection': 'close', 'x-content-type-options': 'nosniff' });
    res.end(body);
  };
  try {
    discovery = await serveDiscovery({ catalog, port });
    control = createServer({ maxHeaderSize: 8192, requestTimeout: 10000,
      headersTimeout: 5000, keepAliveTimeout: 1 }, (req, res) => {
      if (controlTransport === 'loopback' && !authenticatedLoopback(req, controlOrigin, controlSecret))
        return send(res, 403, { ok: false, error: 'PRIVATE_CONTROL_AUTH_REQUIRED' });
      if (closing) return send(res, 503, { ok: false, error: 'OPERATOR_CLOSING' });
      if (req.method !== 'POST' || req.url !== '/v1/command') {
        return send(res, 404, { ok: false, error: 'COMMAND_ENDPOINT_REQUIRED' });
      }
      if (req.headers['content-type'] !== 'application/json' || req.headers['transfer-encoding'] ||
          !/^[1-9][0-9]{0,6}$/.test(req.headers['content-length'] ?? '') ||
          Number(req.headers['content-length']) > MAX_COMMAND) {
        return send(res, 413, { ok: false, error: 'BOUNDED_JSON_COMMAND_REQUIRED' });
      }
      const commandBytes = Number(req.headers['content-length']);
      if (inFlight >= 16 || reservedBytes + commandBytes > MAX_QUEUED_BYTES)
        return send(res, 429, { ok: false, error: 'LOCAL_COMMAND_CAPACITY' });
      inFlight++; reservedBytes += commandBytes;
      let released = false;
      const release = () => { if (!released) { released = true; inFlight--; reservedBytes -= commandBytes; } };
      const chunks = [];
      let size = 0, complete = false;
      req.on('error', release);
      req.on('aborted', release);
      req.on('data', chunk => {
        size += chunk.length;
        if (size > MAX_COMMAND) { release(); req.destroy(); return; }
        chunks.push(chunk);
      });
      req.on('end', () => {
        if (complete) return;
        complete = true;
        if (closing) {
          release(); send(res, 503, { ok: false, error: 'OPERATOR_CLOSING' }); return;
        }
        let command;
        try {
          if (size !== Number(req.headers['content-length'])) fail('COMMAND_LENGTH_MISMATCH');
          command = JSON.parse(Buffer.concat(chunks).toString('utf8'));
        } catch {
          release(); send(res, 400, { ok: false, error: 'INVALID_COMMAND_JSON' }); return;
        }
        void serialize(command).then(result => {
          send(res, 200, { ok: true, requestId: command.requestId, result });
        }, error => {
          const code = /^[A-Z][A-Z0-9_]{2,100}$/.test(error?.message ?? '') ?
            error.message : 'OPERATOR_COMMAND_REJECTED';
          send(res, 422, { ok: false, requestId: id(command?.requestId) ? command.requestId : null,
            error: code });
        }).finally(release);
      });
    });
    control.maxRequestsPerSocket = 1;
    control.on('connection', socket => {
      connections.add(socket); socket.on('close', () => connections.delete(socket));
    });
    control.on('clientError', (_error, socket) => socket.destroy());
    await new Promise((done, reject) => {
      control.once('error', reject);
      const listening = () => { control.off('error', reject); done(); };
      if (controlTransport === 'loopback') control.listen(0, '127.0.0.1', listening);
      else control.listen(socketPath, listening);
    });
    if (controlTransport === 'unix') await chmod(socketPath, 0o600);
    else {
      controlOrigin = `http://127.0.0.1:${control.address().port}`;
      const bytes = Buffer.from(JSON.stringify({ schema: CONTROL_DESCRIPTOR_SCHEMA,
        transport: 'loopback', origin: controlOrigin, token: controlSecret.toString('hex'),
        processId: process.pid, createdAt: new Date().toISOString() }) + '\n');
      let descriptor;
      try {
        descriptor = await open(descriptorPath, 'wx', 0o600);
        const meta = await descriptor.stat();
        descriptorIdentity = { dev: meta.dev, ino: meta.ino, sha256: sha(bytes), complete: false };
        await descriptor.writeFile(bytes); await descriptor.sync();
        descriptorIdentity.complete = true;
      } finally { bytes.fill(0); await descriptor?.close(); }
      await syncDirectory(target);
    }
  } catch (error) {
    closing = true;
    try {
      if (control?.listening) {
        const stopped = new Promise(done => control.close(done));
        await Promise.allSettled([...pending]);
        for (const connection of connections) connection.destroy();
        await stopped;
      }
    } finally {
      controlSecret?.fill(0);
      try { await removeOwnDescriptor(); }
      finally {
        if (discovery) await discovery.close().catch(() => {});
        await catalog.close();
      }
    }
    throw error;
  }
  return {
    origin: discovery.origin, controlTransport,
    ...(controlTransport === 'unix' ? { socketPath } : { controlOrigin, descriptorPath }),
    policySha256: policy.sourceSha256,
    close() {
      if (!closePromise) closePromise = (async () => {
        closing = true;
        const stopped = new Promise((done, reject) =>
          control.close(error => error ? reject(error) : done()));
        control.closeIdleConnections();
        let socketDeadline;
        try {
          // Accepted writes complete before any control connection is forced
          // closed. Incomplete request bodies are never admitted during drain.
          await Promise.allSettled([...pending]);
          for (const connection of connections) connection.end();
          socketDeadline = setTimeout(() => {
            for (const connection of connections) connection.destroy();
          }, 2000);
          await stopped;
        } finally {
          clearTimeout(socketDeadline);
          controlSecret?.fill(0);
          try { await removeOwnDescriptor(); }
          finally {
            try { await discovery.close(); }
            finally { await catalog.close(); }
          }
        }
      })();
      return closePromise;
    },
  };
}

/** Single attempt, exact source bytes. A transport failure after a write leaves
 * its outcome unknown; inspect status/lookup/history instead of blind retries.
 */
export async function requestCatalogOperator({ directory, operation, input = {},
  requestId = randomUUID(), timeoutMs = 30000, signal } = {}) {
  if (signal !== undefined && !(signal instanceof AbortSignal)) fail('ABORT_SIGNAL_REQUIRED');
  const abortError = () => Object.assign(new Error('LOCAL_OPERATOR_ABORTED'), { commandSent: false, requestId });
  if (signal?.aborted) throw abortError();
  const target = resolve(directory), socketPath = join(target, SOCKET_NAME);
  const meta = await lstat(target);
  if (!meta.isDirectory() || meta.isSymbolicLink() || await realpath(target) !== target ||
      (meta.mode & 0o077) !== 0 || (process.getuid && meta.uid !== process.getuid())) {
    fail('OWNED_PRIVATE_OPERATOR_SOCKET_REQUIRED');
  }
  let descriptor;
  try { descriptor = await readControlDescriptor(join(target, CONTROL_DESCRIPTOR_NAME)); }
  catch (error) { if (error.code !== 'ENOENT') throw error; }
  let destination, authorization;
  if (descriptor) {
    try { await lstat(socketPath); fail('CONTROL_TRANSPORT_MARKERS_CONFLICT'); }
    catch (error) { if (error.code !== 'ENOENT') throw error; }
    const origin = new URL(descriptor.origin);
    destination = { hostname: '127.0.0.1', port: Number(origin.port), protocol: 'http:' };
    authorization = 'Bearer ' + descriptor.token;
    descriptor.token = null;
  } else {
    const socketMeta = await lstat(socketPath);
    if (!socketMeta.isSocket() || (socketMeta.mode & 0o077) !== 0 ||
        (process.getuid && socketMeta.uid !== process.getuid())) fail('OWNED_PRIVATE_OPERATOR_SOCKET_REQUIRED');
    destination = { socketPath };
  }
  if (signal?.aborted) throw abortError();
  if (!Number.isInteger(timeoutMs) || timeoutMs < 100 || timeoutMs > 120000) fail('TIMEOUT_INVALID');
  const body = JSON.stringify({ schema: CONTROL_SCHEMA, requestId, operation, input });
  if (Buffer.byteLength(body) > MAX_COMMAND) fail('COMMAND_TOO_LARGE');
  return new Promise((done, reject) => {
    let sent = false, settled = false;
    const finish = (error, value) => {
      if (settled) return;
      settled = true; clearTimeout(timer);
      signal?.removeEventListener('abort', onAbort);
      if (error) {
        error.commandSent = sent;
        error.requestId = requestId;
        reject(error);
      } else done(value);
    };
    const req = httpRequest({ ...destination, method: 'POST', path: '/v1/command', agent: false,
      headers: { 'content-type': 'application/json', 'content-length': Buffer.byteLength(body),
        'connection': 'close', ...(authorization ? { authorization } : {}) } }, res => {
      const chunks = []; let size = 0;
      res.on('data', chunk => {
        size += chunk.length;
        if (size > MAX_RESPONSE) { req.destroy(new Error('CONTROL_RESPONSE_TOO_LARGE')); return; }
        chunks.push(chunk);
      });
      res.on('error', error => finish(error));
      res.on('end', () => {
        try {
          const reply = JSON.parse(Buffer.concat(chunks).toString('utf8'));
          if (res.statusCode !== 200 || reply.ok !== true) {
            const error = new Error(reply.error ?? 'OPERATOR_REQUEST_REJECTED');
            error.statusCode = res.statusCode;
            finish(error); return;
          }
          if (reply.requestId !== requestId) fail('CONTROL_RESPONSE_ID_MISMATCH');
          finish(null, reply.result);
        } catch (error) { finish(error); }
      });
    });
    const onAbort = () => req.destroy(abortError());
    const timer = setTimeout(() => req.destroy(new Error('LOCAL_OPERATOR_TIMEOUT')), timeoutMs);
    req.on('finish', () => { sent = true; });
    req.on('error', error => finish(error));
    signal?.addEventListener('abort', onAbort, { once: true });
    if (signal?.aborted) onAbort();
    else req.end(body);
  });
}

const USAGE = 'node operator.mjs --directory PRIVATE_DIR --policy TRUSTED_POLICY.json [--port 8787] [--control unix|loopback] [--create-empty]';
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    const args = process.argv.slice(2), options = {}, seen = new Set();
    if (args.length === 1 && args[0] === '--help') console.log(USAGE);
    else {
      for (let i = 0; i < args.length; i++) {
        const key = args[i];
        if (seen.has(key) || !['--directory', '--policy', '--port', '--control', '--create-empty'].includes(key)) fail(USAGE);
        seen.add(key);
        if (key === '--create-empty') { options.createEmpty = true; continue; }
        const value = args[++i];
        if (!value || value.startsWith('--')) fail(USAGE);
        if (key === '--directory') options.directory = value;
        if (key === '--policy') options.policyFile = value;
        if (key === '--control') options.controlTransport = value;
        if (key === '--port') {
          if (!/^[0-9]{1,5}$/.test(value)) fail(USAGE);
          options.port = Number(value);
        }
      }
      const service = await openCatalogOperator(options);
      console.log(JSON.stringify({ state: 'LISTENING', origin: service.origin,
        controlTransport: service.controlTransport, socketPath: service.socketPath,
        controlOrigin: service.controlOrigin, descriptorPath: service.descriptorPath,
        policySha256: service.policySha256 }));
      const stop = () => { service.close().catch(error => {
        console.error(error?.message ?? String(error)); process.exitCode = 1;
      }); };
      process.once('SIGINT', stop); process.once('SIGTERM', stop);
    }
  } catch (error) { console.error(error?.message ?? String(error)); process.exitCode = 1; }
}

// MIT. One synchronous read of selected ORIGINAL native lifecycle revisions.
import { createHash } from 'node:crypto';

export const REVISION_SNAPSHOT_SCHEMA = 'stellar-forge.catalog-revision-snapshot/v1';
export const MAX_REVISION_TARGETS = 1000;
export const MAX_REVISION_PAGE_BYTES = 4 * 1024 * 1024;
const plain = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const hex = value => typeof value === 'string' && /^[a-f0-9]{64}$/.test(value);
const fail = code => { throw new Error(code); };
export const revisionTargetKey = target => JSON.stringify([target.catalogKey, target.sequence]);
export const revisionTargetsDigest = targets => createHash('sha256').update(JSON.stringify(targets)).digest('hex');

/** Keep the complete query with each page. Continuations bind its exact order and head. */
export function validateRevisionSelection(input) {
  if (!plain(input) || !Object.hasOwn(input, 'targets') ||
      Object.keys(input).some(key => !['targets', 'offset', 'expectedHead', 'expectedTargets', 'pageBytes'].includes(key)))
    fail('REVISION_SELECTION_FIELDS_INVALID');
  const { targets, offset = 0, expectedHead, expectedTargets, pageBytes = MAX_REVISION_PAGE_BYTES } = input;
  if (!Array.isArray(targets) || targets.length < 1 || targets.length > MAX_REVISION_TARGETS)
    fail('REVISION_TARGET_LIMIT');
  for (const target of targets) {
    if (!plain(target) || Object.keys(target).length !== 2 ||
        typeof target.catalogKey !== 'string' || !target.catalogKey.length || target.catalogKey.length > 4096 ||
        !Number.isSafeInteger(target.sequence) || target.sequence < 1) fail('REVISION_TARGET_INVALID');
  }
  if (!Number.isSafeInteger(offset) || offset < 0 || offset >= targets.length) fail('REVISION_OFFSET_INVALID');
  if (!Number.isSafeInteger(pageBytes) || pageBytes < 16384 || pageBytes > MAX_REVISION_PAGE_BYTES)
    fail('REVISION_PAGE_BYTES_INVALID');
  const targetsSha256 = revisionTargetsDigest(targets);
  if (expectedHead !== undefined && !hex(expectedHead)) fail('REVISION_HEAD_INVALID');
  if (expectedTargets !== undefined && (!hex(expectedTargets) || expectedTargets !== targetsSha256))
    fail('REVISION_TARGETS_CHANGED');
  if (offset && (expectedHead === undefined || expectedTargets === undefined)) fail('REVISION_CONTINUATION_BINDING_REQUIRED');
  return { targets, offset, expectedHead, targetsSha256, pageBytes };
}

/** lookup/revision are synchronous original in-memory projections under the writer's
 * serialized command. No snapshots are retained, no second index/store is created.
 * Only detached selected revisions leave the native lifecycle, never whole histories.
 */
export function buildRevisionSnapshot(input, { head, count, lookup, revision }) {
  const { targets, offset, expectedHead, targetsSha256, pageBytes } = validateRevisionSelection(input);
  if (expectedHead !== undefined && expectedHead !== head) fail('REVISION_SNAPSHOT_HEAD_CHANGED');
  const rows = [], currentByKey = new Map();
  let bytes = 1024, next = offset;
  for (; next < targets.length; next++) {
    const target = targets[next];
    if (!currentByKey.has(target.catalogKey)) currentByKey.set(target.catalogKey, lookup(target.catalogKey));
    const current = currentByKey.get(target.catalogKey);
    const selected = current ? revision(current.lifecycleId, target.sequence) : null;
    const row = { catalogKey: target.catalogKey, sequence: target.sequence, current,
      history: selected ? [selected] : [] };
    const rowBytes = Buffer.byteLength(JSON.stringify(row)) + 1;
    if (bytes + rowBytes > pageBytes) {
      if (!rows.length) fail('REVISION_PAGE_LIMIT_TOO_SMALL');
      break;
    }
    bytes += rowBytes; rows.push(row);
  }
  return { schema: REVISION_SNAPSHOT_SCHEMA, journalHead: head, committedOperations: count,
    targetsSha256, total: targets.length, offset, nextOffset: next < targets.length ? next : null,
    rows, maxPageBytes: pageBytes };
}

/** Validate native paging before it is used as recovery evidence. Exported so a
 * caller already holding an authenticated operator response need not read it again.
 */
export function validateRevisionPage(page, { targets, offset, head, policySha256 } = {}) {
  if (!plain(page) || page.schema !== REVISION_SNAPSHOT_SCHEMA || !hex(page.journalHead) ||
      !hex(page.policySha256) || page.targetsSha256 !== revisionTargetsDigest(targets) ||
      page.total !== targets.length || page.offset !== offset || !Array.isArray(page.rows) ||
      !page.rows.length || page.rows.length > targets.length - offset) fail('NATIVE_REVISION_PAGE_INVALID');
  if (head !== undefined && page.journalHead !== head) fail('REVISION_SNAPSHOT_HEAD_CHANGED');
  if (policySha256 !== undefined && page.policySha256 !== policySha256) fail('REVISION_SNAPSHOT_POLICY_CHANGED');
  const end = offset + page.rows.length;
  if (page.nextOffset !== (end < targets.length ? end : null)) fail('NATIVE_REVISION_PAGE_PROGRESS_INVALID');
  for (const [index, row] of page.rows.entries()) {
    const target = targets[offset + index];
    if (!plain(row) || row.catalogKey !== target.catalogKey || row.sequence !== target.sequence ||
        !(row.current === null || plain(row.current)) || !Array.isArray(row.history) || row.history.length > 1 ||
        row.history.some(item => !plain(item) || item.sequence !== target.sequence) ||
        (row.current === null && row.history.length)) fail('NATIVE_REVISION_PAGE_ROW_INVALID');
  }
  return page;
}

// MIT. Read-only HTTP delivery of the original SF60 durable Bazaar catalog.
import { createServer } from 'node:http';
import { stat } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createDiscoveryServer } from '../../../scf46-stellar-bazaar/src/catalog.mjs';
import { DurableCatalogTransaction } from './journal.mjs';

const HOST = '127.0.0.1';
const FILE = 'catalog-commits.json';
const ROUTES = new Set(['/discovery/resources', '/discovery/search']);
const COMMON_HEADERS = Object.freeze({
  'cache-control': 'no-store',
  'x-content-type-options': 'nosniff',
  'referrer-policy': 'no-referrer',
  'content-security-policy': "default-src 'none'; frame-ancestors 'none'",
});

/** Mount a journal already owned by an authenticated operator process.
 * Closing the HTTP listener does not close or mutate the supplied catalog.
 * The original journal remains responsible for admission, commit and retirement.
 */
export async function serveDiscovery({ catalog, port = 0 } = {}) {
  if (!(catalog instanceof DurableCatalogTransaction)) {
    throw new TypeError('An open original DurableCatalogTransaction is required');
  }
  if (!Number.isInteger(port) || port < 0 || port > 65535) throw new RangeError('Invalid port');
  // Fail before listening if the existing owner's journal is closed/poisoned.
  catalog.list(new URLSearchParams({ limit: '1' }));
  const discovery = createDiscoveryServer(catalog);
  let origin = '';
  let closing;
  const server = createServer({ maxHeaderSize: 8192, requestTimeout: 10000,
    headersTimeout: 10000, keepAliveTimeout: 2000 }, (req, res) => {
    for (const [name, value] of Object.entries(COMMON_HEADERS)) res.setHeader(name, value);
    const reply = (status, value) => {
      res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
      res.end(JSON.stringify(value));
    };
    if (req.socket.localAddress !== HOST || req.socket.remoteAddress !== HOST ||
        req.headers.host !== origin.slice('http://'.length) ||
        (req.headers.origin && req.headers.origin !== origin) ||
        req.headers['sec-fetch-site'] === 'cross-site') {
      return reply(403, { error: 'LOCAL_ORIGIN_REQUIRED' });
    }
    if (req.method !== 'GET') {
      res.setHeader('allow', 'GET');
      res.setHeader('connection', 'close');
      return reply(405, { error: 'GET_ONLY' });
    }
    if (req.headers['transfer-encoding'] ||
        (req.headers['content-length'] && req.headers['content-length'] !== '0')) {
      res.setHeader('connection', 'close');
      return reply(400, { error: 'REQUEST_BODY_NOT_ACCEPTED' });
    }
    if (typeof req.url !== 'string' || req.url.length > 4096 || !req.url.startsWith('/') || req.url.startsWith('//')) {
      return reply(400, { error: 'INVALID_REQUEST_TARGET' });
    }
    let url;
    try { url = new URL(req.url, origin); }
    catch { return reply(400, { error: 'INVALID_REQUEST_TARGET' }); }
    if (url.pathname === '/healthz' && !url.search) {
      try {
        const page = catalog.list(new URLSearchParams({ limit: '1' }));
        return reply(200, { status: 'ready', mode: 'READ_ONLY_DISCOVERY',
          activeResources: page.pagination.total, committedOperations: catalog.count,
          journalHead: catalog.head });
      } catch {
        return reply(503, { status: 'unavailable', error: 'JOURNAL_UNAVAILABLE' });
      }
    }
    if (!ROUTES.has(url.pathname)) return reply(404, { error: 'NOT_FOUND' });
    // Preserve the actual Bazaar response, filtering, ranking and cursor semantics.
    void discovery(req, res);
  });
  server.on('clientError', (_error, socket) => {
    if (socket.writable) socket.end('HTTP/1.1 400 Bad Request\r\nConnection: close\r\n\r\n');
    else socket.destroy();
  });
  await new Promise((done, fail) => {
    server.once('error', fail);
    server.listen(port, HOST, () => { server.off('error', fail); done(); });
  });
  origin = `http://${HOST}:${server.address().port}`;
  return {
    server, origin,
    close() {
      if (!closing) closing = new Promise((done, fail) => {
        server.close(error => error ? fail(error) : done());
        server.closeIdleConnections();
      });
      return closing;
    },
  };
}

/** Standalone owner: retain the original SF60 exclusive lock for the full service
 * lifetime. Never steal another writer's lock or modify its journal externally.
 */
export async function openDiscovery({ directory, port = 0, createEmpty = false } = {}) {
  if (typeof directory !== 'string' || !directory.trim()) throw new TypeError('Explicit journal directory required');
  if (typeof createEmpty !== 'boolean') throw new TypeError('createEmpty must be boolean');
  const target = resolve(directory);
  if (!createEmpty) {
    try {
      if (!(await stat(join(target, FILE))).isFile()) throw new Error('Not a regular journal file');
    } catch (error) {
      if (error.code === 'ENOENT') throw new Error('No existing catalog-commits.json; use --create-empty only for an intentionally empty catalog');
      throw error;
    }
  }
  let catalog;
  try { catalog = await DurableCatalogTransaction.open(target); }
  catch (error) {
    if (error.code === 'EEXIST') throw new Error('SF60 journal already has an owner. Mount serveDiscovery({catalog}) inside that process or stop it cleanly first. The lock was preserved.');
    throw error;
  }
  let listener;
  try { listener = await serveDiscovery({ catalog, port }); }
  catch (error) { await catalog.close(); throw error; }
  let closing;
  return {
    server: listener.server, origin: listener.origin,
    close() {
      if (!closing) closing = (async () => {
        try { await listener.close(); }
        finally { await catalog.close(); }
      })();
      return closing;
    },
  };
}

const USAGE = 'node service.mjs --directory PATH [--port 0..65535] [--create-empty]';
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    const args = process.argv.slice(2);
    if (args.length === 1 && args[0] === '--help') {
      console.log(USAGE);
    } else {
      const options = {}, seen = new Set();
      for (let i = 0; i < args.length; i++) {
        const name = args[i];
        if (seen.has(name) || !['--directory', '--port', '--create-empty'].includes(name)) throw new Error(USAGE);
        seen.add(name);
        if (name === '--create-empty') { options.createEmpty = true; continue; }
        const value = args[++i];
        if (!value || value.startsWith('--')) throw new Error(USAGE);
        if (name === '--directory') options.directory = value;
        else {
          if (!/^\d{1,5}$/.test(value)) throw new Error(USAGE);
          options.port = Number(value);
        }
      }
      const service = await openDiscovery(options);
      console.log(JSON.stringify({ status: 'LISTENING', origin: service.origin,
        resources: service.origin + '/discovery/resources', search: service.origin + '/discovery/search',
        health: service.origin + '/healthz', ownership: 'EXCLUSIVE_SF60_OWNER', readOnly: true }));
      const stop = () => { service.close().catch(error => { console.error(error.message); process.exitCode = 1; }); };
      process.once('SIGINT', stop);
      process.once('SIGTERM', stop);
    }
  } catch (error) { console.error(String(error.message ?? error)); process.exitCode = 1; }
}

#!/usr/bin/env node
import { readFile, lstat, mkdir, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { dirname, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { importOpenApi } from './importer.mjs';
import { parseOpenApiSource } from './source-document.mjs';
const sha = data => createHash('sha256').update(data).digest('hex');

export async function run(args = process.argv.slice(2), {report = true} = {}) {
  if (args[0] === 'har') return (await import('./har/cli.mjs')).runHarCLI(args.slice(1));
  if (args[0] === 'postman') return (await import('./postman/cli.mjs')).runPostmanCLI(args.slice(1));
  if (args[0] === 'weather') return (await import('./openweather/cli.mjs')).main(args.slice(1));
  if (args[0] === 'refresh') return (await import('./refresh-cli.mjs')).run(args.slice(1));
  if (args[0] === 'source')
    return (await import('./source-bundle-cli.mjs')).runSourceBundleCLI(args.slice(1));
  const options = new Map();
  for (let i = 0; i < args.length; i += 2) {
    if (!['--spec', '--config', '--out', '--service-bindings', '--upstream-bindings'].includes(args[i]) || !args[i + 1] || args[i + 1].startsWith('--') || options.has(args[i]))
      throw new Error('Usage: node cli.mjs --spec openapi.json --config selections.json --out NEW_DIRECTORY [--service-bindings bindings.json] [--upstream-bindings upstreams.json]');
    options.set(args[i], args[i + 1]);
  }
  if (!['--spec', '--config', '--out'].every(key => options.has(key))) throw new Error('Supply --spec, --config and --out');
  if (options.has('--upstream-bindings') && !options.has('--service-bindings'))
    throw new Error('--upstream-bindings requires --service-bindings');
  const input = async name => {
    const path = options.get(name), stat = await lstat(path);
    if (!stat.isFile() || stat.size > 4 * 1024 * 1024) throw new Error(name + ' requires a regular source file up to 4 MiB');
    const bytes = await readFile(path);
    if (bytes.length > 4 * 1024 * 1024) throw new Error('Input grew beyond size limit');
    const text=new TextDecoder('utf-8',{fatal:true,ignoreBOM:name==='--spec'}).decode(bytes);
    return { bytes, value:name==='--spec'?parseOpenApiSource(text).document:JSON.parse(text) };
  };
  const spec = await input('--spec'), config = await input('--config');
  const compiled = importOpenApi(spec.value, config.value);
  const bytes = Buffer.from(JSON.stringify(compiled, null, 2) + '\n');
  const bindings = options.has('--service-bindings') ? await input('--service-bindings') : null;
  // Metadata-only import need not load a network resource-server module.
  const createSellerServiceConfig = bindings
    ? (await import('./service-config.mjs')).createSellerServiceConfig : null;
  const serviceConfig = bindings ? createSellerServiceConfig(compiled, bindings.value) : null;
  const upstreamInput = options.has('--upstream-bindings') ? await input('--upstream-bindings') : null;
  let upstreamBytes = null;
  if (upstreamInput) {
    const { createContractUpstreamBindings } = await import('./response-contracts.mjs');
    const upstreams = createContractUpstreamBindings(spec.value, compiled, bindings.value, upstreamInput.value,
      { specSha256: sha(spec.bytes) });
    upstreamBytes = Buffer.from(JSON.stringify(upstreams, null, 2) + '\n');
    if (upstreamBytes.length > 1048576) throw new RangeError('Upstream config exceeds the SF30 1 MiB limit');
  }
  const responseFiles = [];
  if (serviceConfig?.routes.some(route => Object.hasOwn(route, 'responseFile'))) {
    const { readJsonResponseFile } = await import('../sf30-seller-sdk/response-file.mjs');
    for (const route of serviceConfig.routes) {
      if (!Object.hasOwn(route, 'responseFile')) continue;
      let snapshot;
      try {
        snapshot = await readJsonResponseFile(resolve(dirname(resolve(options.get('--service-bindings'))), route.responseFile));
      } catch (error) {
        throw new Error(`Route ${route.id} responseFile: ${error.message}`, { cause: error });
      }
      route.responseFile = 'responses/' + route.id + '.json';
      responseFiles.push({ routeId: route.id, file: route.responseFile, bytes: snapshot.source });
    }
  }
  const serviceBytes = serviceConfig ? Buffer.from(JSON.stringify(serviceConfig, null, 2) + '\n') : null;
  if (serviceBytes && serviceBytes.length > 1024 * 1024) throw new RangeError('Service config exceeds the SF30 1 MiB limit');
  const native = await readFile(new URL('../sf30-seller-discovery/index.mjs', import.meta.url));
  const adapter = await readFile(new URL('./importer.mjs', import.meta.url));
  const validator = await readFile(new URL('../../../stellar-forge/payment-auto-catalog/schema-validation.mjs', import.meta.url));
  const compatibility = await readFile(new URL('./schema-compat.mjs', import.meta.url));
  const manifest = { schema: 'stellar.open-api-seller-manifest.v1',
    specSha256: sha(spec.bytes), selectionsSha256: sha(config.bytes),
    sellerCompilerSha256: sha(native), validatorSha256: sha(validator), importerSha256: sha(adapter), offersSha256: sha(bytes),
    schemaCompatibilitySha256: sha(compatibility),
    operations: compiled.offers.map(({ method, path, sourcePointer, serverIndex }) => ({ method, path, sourcePointer, serverIndex })) };
  if (serviceBytes) {
    manifest.serviceBindingsSha256 = sha(bindings.bytes);
    manifest.serviceConfigSha256 = sha(serviceBytes);
    manifest.serviceAdapterSha256 = sha(await readFile(new URL('./service-config.mjs', import.meta.url)));
  }
  if (responseFiles.length) {
    manifest.responseFiles = responseFiles.map(({ routeId, file, bytes }) => ({ routeId, file, sha256: sha(bytes) }));
    manifest.responseFileLoaderSha256 = sha(await readFile(new URL('../sf30-seller-sdk/response-file.mjs', import.meta.url)));
  }
  if (upstreamBytes) {
    manifest.upstreamBindingsSha256 = sha(upstreamInput.bytes);
    manifest.upstreamConfigSha256 = sha(upstreamBytes);
    manifest.responseContractCompilerSha256 = sha(await readFile(new URL('./response-contracts.mjs', import.meta.url)));
    manifest.responseContractRuntimeSha256 = sha(await readFile(new URL('../sf30-seller-sdk/response-contract.mjs', import.meta.url)));
  }
  const output = resolve(options.get('--out'));
  await mkdir(output, { mode: 0o700 });
  if (responseFiles.length) {
    await mkdir(resolve(output, 'responses'), { mode: 0o700 });
    for (const { file, bytes } of responseFiles) await writeFile(resolve(output, file), bytes, { flag: 'wx', mode: 0o600 });
  }
  await writeFile(resolve(output, 'offers.json'), bytes, { flag: 'wx', mode: 0o600 });
  if (serviceBytes) await writeFile(resolve(output, 'seller-service.json'), serviceBytes, { flag: 'wx', mode: 0o600 });
